const repo = $input.first().json;

return [
  {
    json: {
      name: repo.name,
      fullName: repo.full_name,
      description: repo.description,
      url: repo.html_url,
      language: repo.language,
      stars: repo.stargazers_count,
      forks: repo.forks_count,
      openIssues: repo.open_issues_count,
      defaultBranch: repo.default_branch,
      topics: repo.topics ?? [],
      lastUpdated: repo.updated_at,
    },
  },
];

const input = $input.first().json;

// Read the repository URL from the Webhook input.
const repositoryUrl =
  input.body?.repository ??
  input.repository ??
  input.body?.body?.repository;

function invalid(error) {
  return [
    {
      json: {
        isValid: false,
        error,
      },
    },
  ];
}

// Check that the input is a string.
if (typeof repositoryUrl !== "string") {
  return invalid("Expected a repository URL in the repository field.");
}

// Remove accidental whitespace.
const candidate = repositoryUrl.trim();

// Accept only HTTPS GitHub repository URLs.
// Reject issue pages, subdirectories, query strings, and fragments.
const match = candidate.match(
  /^https:\/\/github\.com\/([A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?)\/([A-Za-z0-9._-]{1,100})\/?$/i
);

if (!match) {
  return invalid(
    "Use a GitHub repository URL, such as https://github.com/vercel/next.js"
  );
}

const [, owner, repo] = match;

if (repo === "." || repo === "..") {
  return invalid("The repository name is invalid.");
}

// Construct our output from validated components.
return [
  {
    json: {
      isValid: true,
      owner,
      repo,
      repositoryUrl: `https://github.com/${owner}/${repo}`,
      apiUrl: `https://api.github.com/repos/${owner}/${repo}`,
    },
  },
];

const response = $input.first().json;

// The Search API places matching results inside "items".
const rawIssues = Array.isArray(response.items)
  ? response.items
  : $input.all().map(item => item.json);

const issues = rawIssues
  .filter(issue => !issue.pull_request)
  .map(issue => ({
    number: issue.number,
    title: issue.title,
    url: issue.html_url,
    body: (issue.body ?? "").slice(0, 1200),
    labels: (issue.labels ?? []).map(label => label.name),
    comments: issue.comments,
    updatedAt: issue.updated_at,
  }))
  .slice(0, 5);

return [
  {
    json: {
      issueCount: issues.length,
      issues,
    },
  },
];

const issueResult = $input.first().json;

// Retrieve the repository summary from its earlier node.
const repo = $("Summarize Repository").first().json;

const issues = Array.isArray(issueResult.issues)
  ? issueResult.issues
  : [];

return [
  {
    json: {
      repository: {
        name: repo.name,
        fullName: repo.fullName,
        description: repo.description,
        url: repo.url,
        language: repo.language,
        stars: repo.stars,
        openIssues: repo.openIssues,
        defaultBranch: repo.defaultBranch,
        topics: repo.topics ?? [],
      },
      issueCount: issues.length,
      issues: issues.map(issue => ({
        number: issue.number,
        title: issue.title,
        url: issue.url,
        body: (issue.body ?? "").slice(0, 800),
        labels: issue.labels ?? [],
        comments: issue.comments ?? 0,
        updatedAt: issue.updatedAt,
      })),
    },
  },
];

