const response = $input.first().json;
const candidate = response.candidates?.[0];

if (!candidate || candidate.finishReason !== "STOP") {
  throw new Error(
    `Gemini did not finish successfully: ${
      candidate?.finishReason ?? "no candidate"
    }`
  );
}

// Extract the generated JSON text from Gemini's API response.
const text = candidate.content?.parts
  ?.find(part => typeof part.text === "string")
  ?.text;

if (!text) {
  throw new Error("Gemini returned no text to parse.");
}

// Convert the JSON string into a JavaScript object.
let generated;

try {
  generated = JSON.parse(text);
} catch {
  throw new Error("Gemini returned invalid JSON.");
}

// Retrieve the evidence supplied to Gemini earlier.
const context = $("Build Quest Context").first().json;
const sourceIssues = context.issues ?? [];

const issuesByNumber = new Map(
  sourceIssues.map(issue => [
    Number(issue.number),
    issue,
  ])
);

// Require exactly three quests.
if (!Array.isArray(generated.quests) ||
    generated.quests.length !== 3) {
  throw new Error("Expected exactly three quests.");
}

const quests = generated.quests.map((quest, index) => {
  const numbers = quest.evidenceIssueNumbers;

  if (!Array.isArray(numbers) || numbers.length === 0) {
    throw new Error(
      `Quest ${index + 1} has no evidence issue numbers.`
    );
  }

  const uniqueNumbers = [...new Set(numbers.map(Number))];

  // Reject references that weren't present in our GitHub evidence.
  const evidenceIssues = uniqueNumbers.map(number => {
    const issue = issuesByNumber.get(number);

    if (!issue) {
      throw new Error(
        `Quest ${index + 1} referenced unknown issue #${number}.`
      );
    }

    // Use the original GitHub data, not AI-generated URLs.
    return {
      number: issue.number,
      title: issue.title,
      url: issue.url,
    };
  });

  if (
    typeof quest.title !== "string" ||
    typeof quest.goal !== "string" ||
    !Array.isArray(quest.steps) ||
    !Array.isArray(quest.successCriteria)
  ) {
    throw new Error(
      `Quest ${index + 1} is missing required fields.`
    );
  }

  return {
    title: quest.title,
    difficulty: quest.difficulty,
    goal: quest.goal,
    whyItMatters: quest.whyItMatters,
    steps: quest.steps,
    successCriteria: quest.successCriteria,
    evidenceIssues,
  };
});

return [
  {
    json: {
      repository: context.repository,
      repoSummary: generated.repoSummary,
      quests,
      generation: {
        model: response.modelVersion ?? "unknown",
        finishReason: candidate.finishReason,
      },
    },
  },
];
